#include <bits/stdc++.h>
using namespace std;

const int MAXN = 50005;
const int MAXV = 1024; // 2^10

int N, M;
int A[MAXN];
int par[MAXN], dep[MAXN], heavy[MAXN], headN[MAXN], sz[MAXN];
vector<int> adj[MAXN];

// 树链剖分第一遍DFS
void dfs1(int u, int p) {
    par[u] = p;
    sz[u] = 1;
    heavy[u] = 0;
    dep[u] = p ? dep[p] + 1 : 0;
    int mx = 0;
    for (int v : adj[u]) {
        if (v == p) continue;
        dfs1(v, u);
        sz[u] += sz[v];
        if (sz[v] > mx) {
            mx = sz[v];
            heavy[u] = v;
        }
    }
}

// 树链剖分第二遍DFS
void dfs2(int u, int h) {
    headN[u] = h;
    if (heavy[u]) dfs2(heavy[u], h);
    for (int v : adj[u]) {
        if (v == par[u] || v == heavy[u]) continue;
        dfs2(v, v);
    }
}

// 提取u到v的路径节点序列
vector<int> extractPath(int u, int v) {
    vector<int> l, r;
    while (headN[u] != headN[v]) {
        if (dep[headN[u]] > dep[headN[v]]) {
            int h = headN[u];
            for (int x = u; ; x = par[x]) {
                l.push_back(x);
                if (x == h) break;
            }
            u = par[h];
        } else {
            int h = headN[v];
            for (int x = v; ; x = par[x]) {
                r.push_back(x);
                if (x == h) break;
            }
            v = par[h];
        }
    }
    if (dep[u] <= dep[v]) {
        for (int x = v; ; x = par[x]) {
            r.push_back(x);
            if (x == u) break;
        }
    } else {
        for (int x = u; ; x = par[x]) {
            l.push_back(x);
            if (x == v) break;
        }
    }
    reverse(r.begin(), r.end());
    l.insert(l.end(), r.begin(), r.end());
    return l;
}

int cnt[6][MAXV];
int dp_prev[6], dp_curr[6];

int solve(vector<int>& path, int k) {
    int L = path.size();
    vector<int> S(L + 1);
    S[0] = 0;
    for (int i = 0; i < L; i++) {
        S[i + 1] = S[i] ^ A[path[i]];
    }
    
    for (int j = 0; j <= k; j++) {
        dp_prev[j] = -1;
        dp_curr[j] = -1;
        for (int v = 0; v < MAXV; v++) cnt[j][v] = -1;
    }
    
    dp_prev[0] = 0;
    cnt[0][0] = 0;
    
    for (int i = 1; i <= L; i++) {
        int si = S[i];
        for (int j = 0; j <= k; j++) {
            dp_curr[j] = dp_prev[j];
            if (j > 0) {
                int best = -1;
                for (int v = 0; v < MAXV; v++) {
                    if (cnt[j - 1][v] >= 0) {
                        int val = cnt[j - 1][v] + (v ^ si);
                        if (val > best) best = val;
                    }
                }
                if (best > dp_curr[j]) dp_curr[j] = best;
            }
        }
        for (int j = 0; j <= k; j++) {
            if (dp_curr[j] > cnt[j][si]) cnt[j][si] = dp_curr[j];
        }
        swap(dp_prev, dp_curr);
    }
    
    return dp_prev[k];
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    
    cin >> N >> M;
    for (int i = 1; i <= N; i++) cin >> A[i];
    
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    
    dfs1(1, 0);
    dfs2(1, 1);
    
    for (int q = 0; q < M; q++) {
        int type;
        cin >> type;
        if (type == 1) {
            int u, x;
            cin >> u >> x;
            A[u] = x;
        } else {
            int u, v, k;
            cin >> u >> v >> k;
            vector<int> path = extractPath(u, v);
            cout << solve(path, k) << "\n";
        }
    }
    
    return 0;
}
